import time

from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.utils.param_checker import tput_user_value2normalized

from taf.ue.iphone.data_transfer.utils.ip_addr_selector import get_iphone_ip
from taf.ue.iphone.exceptions import FtpDataTransferFailed, FtpStartFailed


class IphoneFtpDataTransfer(LteDataTransfer):
    """IphoneFtpDataTransfer class"""

    def __init__(self, name, ue_pc, iphone_name, dt_definition, configuration):
        """

        :param name: alias of data transfer
        :param ue_pc: Rpc object responsible for HTTP/HTTPS request
        :param iphone_name: id of iphone, e.g. 00008101-000144860011401E
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from config yaml file
        """
        super().__init__(name, dt_definition, configuration)
        self.dt_id = None
        self.iphone_name = iphone_name
        self.ue_pc = ue_pc

        self.dt_config = self._build_dt_config(dt_definition, configuration)

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        # call get_iphone_ip just for validation that UE has IP
        _ = get_iphone_ip(ue_pc=self.ue_pc, ue_id=self.iphone_name, logger=self.logger)
        self.ue_pc.start_data_transfer(ue_id=self.iphone_name,
                                       data_transfer_id=self.dt_id,
                                       data_transfer_cmd=None,
                                       data_transfer_class="iphoneftp",
                                       data_transfer_config=self.dt_config)
        time.sleep(3)
        data_transfer_status = self.ue_pc.get_data_transfer_state(ue_id=self.iphone_name, data_transfer_id=self.dt_id)
        if data_transfer_status != 'started':
            raise FtpStartFailed(f"FTP data transfer didn't properly started (data_transfer_status={data_transfer_status}).")

    def stop(self):
        """
        Stops already running data transfer.
        :return: None
        """
        raise NotImplementedError("Keyword \"Stop Data Transfer\" isn't implemented for IPhone FTP data transfer, "
                                  "because it makes impossible to read results.\n"
                                  "Instead of it, please use \"Await Data Transfer Finish\".")

    def await_finish(self):
        """
        Waits until this data transfer finish.
        :return: None
        """
        is_running = True
        while is_running:
            data_transfer_status = self.ue_pc.get_data_transfer_state(ue_id=self.iphone_name, data_transfer_id=self.dt_id)
            if data_transfer_status == 'failed':
                raise FtpDataTransferFailed("FTP data transfer failed. Check logs in taf.ue.proxy for details.")
            if data_transfer_status in ['finished', 'stopped']:
                is_running = False
            time.sleep(5)

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="ftp"):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer has finished or raise Exception if not.
        :return: value of Average throughput in unit: KBits/sec
        """
        data_transfer_statistic = self.ue_pc.get_data_transfer_output(ue_id=self.iphone_name,
                                                                      data_transfer_id=self.dt_id,
                                                                      raw_output=True)
        throughput_mbits_sec = data_transfer_statistic.get('throughput', -1)
        return tput_user_value2normalized(f'{throughput_mbits_sec} Mbits/sec')

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        data_transfer_status = self.ue_pc.get_data_transfer_state(ue_id=self.iphone_name, data_transfer_id=self.dt_id)
        self.logger.debug(f"Checking data transfer status (data_transfer_status={data_transfer_status})")
        return data_transfer_status == 'started'

    def release_data_transfer(self):
        """Nothing to release"""
        pass

    def check_data_transfer(self):
        """Not Implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not Implemented"""
        raise NotImplementedError

    def get_data_transfer_statistics(self, **kwargs):
        """Not Implemented"""
        raise NotImplementedError

    def get_datagram_loss(self):
        """Not Implemented"""
        raise NotImplementedError

    # private methods ##############################
    def _build_dt_config(self, dt_definition, configuration):
        direction = dt_definition.direction.lower()
        if direction != 'dl':
            raise AttributeError(f"You're trying run FTP data transfer for \"direction={direction}\", "
                                 f"but currently only \"direction=dl\" is supported.")
        dt_config = {
            'server': configuration['data_transfer']['ftp']['app_server']['address'],
            'password': configuration['data_transfer']['ftp']['app_server']['password'],
            'user': configuration['data_transfer']['ftp']['app_server']['user'],
            'file': dt_definition.protocol_details['filepath'],
            'direction': direction,
            'timeout': dt_definition.protocol_details.get('timeout', 24 * 60 * 60),
        }
        self.dt_id = "{}".format(dt_config['direction'])
        self.logger.debug(f"dt_config: {dt_config}")
        return dt_config
